                    plan.addLeg(newTargetSegmentIndex, msfsSdk.FlightPlan.createLeg(oldDiscoLeg.leg), newTargetSegmentLegIndex + 1, WT21LegDefinitionFlags.DirectTo);
                    plan.addLeg(newTargetSegmentIndex, msfsSdk.FlightPlan.createLeg(oldDtoLeg1.leg), newTargetSegmentLegIndex + 2, WT21LegDefinitionFlags.DirectTo);
                    plan.addLeg(newTargetSegmentIndex, msfsSdk.FlightPlan.createLeg(oldDtoLeg2.leg), newTargetSegmentLegIndex + 3, WT21LegDefinitionFlags.DirectTo | WT21LegDefinitionFlags.DirectToTarget);
