            this.minimumsMode = msfsSdk.ConsumerSubject.create(this.minsSubscriber.on('minimums_mode').whenChanged(), msfsSdk.MinimumsMode.OFF);
            this.alerterState = msfsSdk.Subject.create(MinimumsAlerterState.DISABLED);
